-- ---------------------------------------------------------------------------
-- Sample catalogue data: 5 categories, 16 products, 48 images, 157 specs.
--
-- Import AFTER schema.sql:
--     mysql -u USER -p DATABASE < sql/schema.sql
--     mysql -u USER -p DATABASE < sql/sample_data.sql
--
-- The image rows point at the files in public/uploads/products/sample/.
-- Those are generated placeholders - replace them with your own photographs
-- through the admin panel. Delete everything here once your real products are
-- in:  DELETE FROM products;  DELETE FROM categories;
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE product_specs;
TRUNCATE TABLE product_images;
TRUNCATE TABLE products;
TRUNCATE TABLE categories;
SET FOREIGN_KEY_CHECKS = 1;

