INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `description`, `image_path`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (4,NULL,'Safety Equipment','safety-equipment','Certified personal protective equipment for site and workshop.',NULL,30,1,'2026-08-22 19:58:21','2026-08-22 19:58:21');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `description`, `image_path`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (5,NULL,'Workshop Storage','workshop-storage','Cases, cabinets and benches that keep a workspace in order.',NULL,40,1,'2026-08-22 19:58:21','2026-08-22 19:58:21');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (1,1,'PT-DD1801','Brushless Cordless Drill Driver 18V','brushless-cordless-drill-driver-18v','Compact 18V brushless drill driver with a 13 mm metal chuck and 20-stage clutch.','A brushless motor delivers more torque from the same battery and runs noticeably cooler under load, which is what makes the difference on a long day of repetitive fixings.\n\nThe 13 mm keyless chuck takes round and hex shanks, and the 20-stage clutch plus a dedicated drill mode means you can go from driving small screws in softwood to boring 38 mm holes without swapping tools.\n\nSupplied as a bare unit. Batteries and chargers from the same 18V platform fit without an adapter.',249.00,219.00,'in_stock',34,'Halden',1450,1,1,0,'2026-08-22 19:58:21','2026-08-22 19:58:21');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (2,1,'PT-CS1400','185 mm Circular Saw 1400W','185-mm-circular-saw-1400w','Mains circular saw with a cast aluminium base and 0-56° bevel.','A 1400 W motor and a 185 mm blade give a 62 mm depth of cut at 90°, enough for a 2x4 in a single pass.\n\nThe base is cast rather than pressed, so it stays flat and the cut line stays true. Bevel and depth both lock with cam levers rather than wing nuts.',189.00,NULL,'in_stock',12,'Halden',3900,1,0,1,'2026-08-22 19:58:21','2026-08-22 19:58:21');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (3,1,'PT-OS125','Variable Speed Random Orbit Sander 125 mm','variable-speed-random-orbit-sander-125-mm','Low-vibration 125 mm orbital sander with dust extraction port.','Six speed settings from 7000 to 12000 opm cover everything from paint removal to a final finish before oiling.\n\nThe counterbalanced head keeps vibration under 3 m/s², and the 32 mm port fits standard workshop extraction directly.',129.00,NULL,'low_stock',3,'Halden',1300,1,0,2,'2026-08-22 19:58:21','2026-08-22 19:58:21');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (4,1,'PT-RH0800','SDS-Plus Rotary Hammer 800W','sds-plus-rotary-hammer-800w','Three-mode SDS-plus hammer with vibration-damped side handle.','Rotation, hammer-drilling and chisel-only in one tool, with a safety clutch that releases if the bit binds in reinforcement.\n\nThe side handle is isolated on rubber mounts, which is what makes overhead work with this class of tool tolerable.',279.00,NULL,'preorder',NULL,'Corvent',2800,1,0,3,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (5,2,'HT-CH20','Forged Claw Hammer 20 oz','forged-claw-hammer-20-oz','One-piece forged head with a shock-absorbing hickory handle.','The head and neck are forged from a single billet, so there is no join to loosen. A 20 oz head is the compromise most joiners settle on: heavy enough to sink a 100 mm nail in three strikes, light enough to use all day.\n\nHandle is American hickory, wedged and lacquered.',42.50,NULL,'in_stock',88,'Brackwell',780,1,1,4,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (6,2,'HT-SS94','Chrome Vanadium Socket Set - 94 Piece','chrome-vanadium-socket-set-94-piece','94-piece metric socket set in a latching case, 1/4in and 1/2in drive.','Sockets are chrome vanadium with a satin chrome finish, bi-hex so they grip the flats rather than the corners of a fastener.\n\nBoth ratchets are 72-tooth, which needs only a 5° swing - the difference between reaching a bolt and not.',164.00,139.00,'in_stock',21,'Brackwell',6200,1,1,5,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (7,2,'HT-AW250','Adjustable Wrench 250 mm','adjustable-wrench-250-mm','Wide-opening 250 mm adjustable wrench with a hardened worm screw.','Opens to 34 mm, which covers most plumbing and general fitting work. The scale is laser-etched into the body rather than printed, so it survives being kept in a bag with everything else.',28.90,NULL,'in_stock',46,'Brackwell',520,1,0,6,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (8,2,'HT-CH06','Wood Chisel Set - 6 Piece Bevel Edge','wood-chisel-set-6-piece-bevel-edge','Six bevel-edge chisels, 6 to 32 mm, in a roll.','Blades are chrome manganese steel hardened to 60 HRC and ground to a 25° primary bevel, ready to hone.\n\nThe handles take a mallet without mushrooming, and the canvas roll keeps the edges apart in a bag.',96.00,NULL,'in_stock',17,'Ferrow',1100,1,0,7,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (9,3,'MT-LL02','Self-Levelling Cross Line Laser','self-levelling-cross-line-laser','Green-beam cross line laser, self-levelling to ±4°, 30 m range.','Green beams read roughly four times brighter than red to the human eye, which is what makes this usable in a room with the lights on.\n\nThe pendulum locks for transport - a detail that decides whether a laser survives its first year in a van.',215.00,NULL,'in_stock',9,'Ferrow',640,1,1,8,'2026-08-22 19:58:22','2026-08-22 19:58:22');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (10,3,'MT-DM600','True RMS Digital Multimeter','true-rms-digital-multimeter','CAT III 600V true-RMS meter with a 6000-count backlit display.','True RMS matters the moment you measure anything that is not a clean sine wave - dimmers, variable speed drives, most modern lighting.\n\nRated CAT III 600 V, with fused current inputs and a non-contact voltage detector built into the top of the case.',118.00,NULL,'in_stock',27,'Corvent',380,1,0,9,'2026-08-22 19:58:23','2026-08-22 19:58:23');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (11,3,'MT-VC150','Digital Vernier Caliper 150 mm','digital-vernier-caliper-150-mm','Stainless 150 mm caliper reading to 0.01 mm, metric and imperial.','Hardened stainless jaws for outside, inside, depth and step measurement, with a zero-anywhere button for comparative work.\n\nComes in a fitted case with a spare cell.',54.00,45.00,'in_stock',40,'Ferrow',260,1,0,10,'2026-08-22 19:58:23','2026-08-22 19:58:23');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (12,4,'SE-HH01','Safety Helmet with Ratchet Harness','safety-helmet-with-ratchet-harness','Vented EN 397 helmet with 6-point harness and 30 mm accessory slots.','The ratchet adjusts one-handed while the helmet is on, and the harness is six-point rather than four, which spreads the load and stops the shell rocking.\n\nStandard 30 mm side slots accept ear defenders and visors.',34.00,NULL,'in_stock',120,'Vantor',380,1,0,11,'2026-08-22 19:58:23','2026-08-22 19:58:23');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (13,4,'SE-GL05','Cut Level D Work Gloves','cut-level-d-work-gloves','HPPE-lined gloves with nitrile palm coating, EN 388 4X43D.','Cut level D is the point where a glove stops being about comfort and starts being about sheet metal and glass.\n\nThe nitrile palm keeps grip on oily parts without turning the glove into a board - they still pass a touchscreen test.',14.50,NULL,'in_stock',340,'Vantor',90,1,0,12,'2026-08-22 19:58:23','2026-08-22 19:58:23');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (14,4,'SE-ED31','Electronic Ear Defenders SNR 31 dB','electronic-ear-defenders-snr-31-db','Level-dependent ear defenders that cut impulse noise but pass speech.','Microphones sample outside sound and cut anything above 82 dB in a few milliseconds, so a nail gun going off nearby is dealt with but the person talking to you is not.\n\nRuns about 180 hours on two AAA cells.',89.00,NULL,'out_of_stock',0,'Vantor',310,1,0,13,'2026-08-22 19:58:24','2026-08-22 19:58:24');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (15,5,'WS-TC03','Stackable Tool Case System - 3 Module Set','stackable-tool-case-system-3-module-set','Three interlocking cases on a wheeled base, IP54 rated.','The modules latch to each other rather than just sitting on top, so the stack stays together when the base is tipped onto its wheels and pulled up a kerb.\n\nSeals are IP54, which is rain on a site, not immersion.',279.00,245.00,'in_stock',15,'Corvent',14200,1,1,14,'2026-08-22 19:58:24','2026-08-22 19:58:24');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `short_description`, `description`, `price`, `sale_price`, `stock_status`, `stock_qty`, `brand`, `weight_grams`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES (16,5,'WS-WB15','Steel Workbench 1500 mm with Vice','steel-workbench-1500-mm-with-vice','Welded steel bench, 1500 mm hardwood top, 750 kg rated.','The frame is welded rather than bolted, so it does not develop a wobble after a year of hammering on it. The 40 mm beech top is oiled and can be sanded back.\n\nA 150 mm quick-release vice is fitted at the left end as standard.',749.00,NULL,'discontinued',1,'Corvent',68000,1,0,15,'2026-08-22 19:58:24','2026-08-22 19:58:24');
